import { vec2, vec3, vec4 } from "gl-matrix";
import { RendererConfig } from "../renderer.js";
import { LambertianMaterial } from "./material.js";
import { SolidColorTexture } from "./texture.js";
export class Config extends RendererConfig {
    constructor() {
        super();
        this.reset();
    }
    standardLightingOptions(options) {
        const azimuthOffset = options && options.azimuthOffset ? options.azimuthOffset : this.lightingAzimuthOffset;
        const altitude = options && options.altitude ? options.altitude : this.lightingAltitude;
        const size = options && options.size ? options.size : this.lightingSize;
        const distance = options && options.distance ? options.distance : this.lightingDistance;
        return [
            {
                azimuth: -45 + azimuthOffset,
                altitude: altitude,
                distance: distance,
                size: vec2.fromValues(size, size),
                yaw: -45 + azimuthOffset,
                pitch: altitude,
                color: vec3.fromValues(10, 10, 10),
            },
            {
                azimuth: 45 + azimuthOffset,
                altitude: altitude,
                distance: distance,
                size: vec2.fromValues(size, size),
                yaw: 45 + azimuthOffset,
                pitch: altitude,
                color: vec3.fromValues(1, 1, 1),
            },
            {
                azimuth: -135 + azimuthOffset,
                altitude: altitude,
                distance: distance,
                size: vec2.fromValues(size, size),
                yaw: -135 + azimuthOffset,
                pitch: altitude,
                color: vec3.fromValues(1, 1, 1),
            }
        ];
    }
    reset() {
        this.aperture = 0;
        this.exposure = 1;
        this.maxSamplesPerPixel = 10000;
        this.shutterSpeed = 0;
        this.raysPerFrame = 1;
        this.maxPrimsInNode = 1;
        this.defaultMaterial = new LambertianMaterial({ texture: new SolidColorTexture({ color: vec3.fromValues(0.5, 0.5, 0.5) }) });
        this.defaultTextMaterial = new LambertianMaterial({ texture: new SolidColorTexture({ color: vec3.fromValues(1, 1, 1) }) });
        this.groundSize = vec2.fromValues(10, 10);
        this.backgroundColor = vec4.fromValues(0, 0, 0, 1);
        this.lightingAzimuthOffset = 0;
        this.lightingAltitude = 30;
        this.lightingSize = 0.5;
        this.lightingDistance = 1.5;
        this.autoDepth = true;
        this.minDepth = 1;
        this.maxDepth = 10;
        this.edgeDepth = 0.01;
        this.edgeNormal = 0.025;
    }
}
