import { quat, vec3 } from "gl-matrix";
import { Constants } from "../../constants.js";
import { AngleHelper } from "../../helpers/angle.js";
import { RendererConfig } from "../renderer.js";
export class Config extends RendererConfig {
    constructor() {
        super();
        this.reset();
    }
    reset() {
        this.specularIntensity = 0.15;
        this.specularPower = 150;
        this.lightPosition = vec3.fromValues(-0.5, 0.5, 0);
        this.ambient = 0.01;
        const _quat1 = quat.create();
        const _quat2 = quat.create();
        let angle = AngleHelper.degreesToRadians(15);
        quat.setAxisAngle(_quat1, Constants.VECTOR3_UNITX, angle);
        quat.multiply(_quat2, _quat1, _quat2);
        angle = AngleHelper.degreesToRadians(-15);
        quat.setAxisAngle(_quat1, Constants.VECTOR3_UNITY, angle);
        quat.multiply(_quat2, _quat2, _quat1);
        this.directionToLight = vec3.create();
        vec3.transformQuat(this.directionToLight, Constants.VECTOR3_UNITZ, _quat2);
        this.halfAngle = vec3.create();
        vec3.add(this.halfAngle, Constants.VECTOR3_UNITZ, this.directionToLight);
        vec3.normalize(this.halfAngle, this.halfAngle);
        this.isFxaaEnabled = false;
    }
}
