import { vec3 } from "gl-matrix";
import { Cube } from "../../meshes/cube.js";
export class AABB {
    get min() { return this._min; }
    get max() { return this._max; }
    constructor() {
        this._min = vec3.fromValues(Number.MAX_VALUE, Number.MAX_VALUE, Number.MAX_VALUE);
        this._max = vec3.fromValues(-Number.MAX_VALUE, -Number.MAX_VALUE, -Number.MAX_VALUE);
    }
    centroid(centroid) {
        centroid[0] = (this._min[0] + this._max[0]) / 2;
        centroid[1] = (this._min[1] + this._max[1]) / 2;
        centroid[2] = (this._min[2] + this._max[2]) / 2;
    }
    size(size) {
        size[0] = this._max[0] - this._min[0];
        size[1] = this._max[1] - this._min[1];
        size[2] = this._max[2] - this._min[2];
    }
    offset(point, normalized) {
        normalized[0] = (point[0] - this._min[0]) / (this._max[0] - this._min[0]);
        normalized[1] = (point[1] - this._min[1]) / (this._max[1] - this._min[1]);
        normalized[2] = (point[2] - this._min[2]) / (this._max[2] - this._min[2]);
    }
    unionBounds(bounds) {
        vec3.min(this._min, this._min, bounds.min);
        vec3.max(this._max, this._max, bounds.max);
    }
    unionPoint(point) {
        vec3.min(this._min, this._min, point);
        vec3.max(this._max, this._max, point);
    }
    maximumExtent() {
        const dx = this._max[0] - this._min[0];
        const dy = this._max[1] - this._min[1];
        const dz = this._max[2] - this._min[2];
        if (dx > dy && dx > dz)
            return 0;
        else if (dy > dz) {
            return 1;
        }
        return 2;
    }
    surfaceArea() {
        const dx = this._max[0] - this._min[0];
        const dy = this._max[1] - this._min[1];
        const dz = this._max[2] - this._min[2];
        return 2 * (dx * dy + dx * dz + dy * dz);
    }
    rotate(rotation) {
        const sizeX = this._max[0] - this._min[0];
        const sizeY = this._max[1] - this._min[1];
        const sizeZ = this._max[2] - this._min[2];
        const min = vec3.fromValues(Number.MAX_VALUE, Number.MAX_VALUE, Number.MAX_VALUE);
        const max = vec3.fromValues(-Number.MAX_VALUE, -Number.MAX_VALUE, -Number.MAX_VALUE);
        const position = vec3.create();
        const vertices = Cube.POSITIONS;
        for (let i = 0; i < 8; i++) {
            vec3.set(position, vertices[i * 3] * sizeX, vertices[i * 3 + 1] * sizeY, vertices[i * 3 + 2] * sizeZ);
            vec3.transformQuat(position, position, rotation);
            vec3.min(min, min, position);
            vec3.max(max, max, position);
        }
        vec3.copy(this._min, min);
        vec3.copy(this._max, max);
    }
    fromCylinder(pa, pb, radius) {
        const a = vec3.create();
        vec3.subtract(a, pb, pa);
        const aa = vec3.dot(a, a);
        const ex = radius * Math.sqrt(1 - a[0] * a[0] / aa);
        const ey = radius * Math.sqrt(1 - a[1] * a[1] / aa);
        const ez = radius * Math.sqrt(1 - a[2] * a[2] / aa);
        this._min[0] = Math.min(pa[0] - ex, pb[0] - ex);
        this._min[1] = Math.min(pa[1] - ey, pb[1] - ey);
        this._min[2] = Math.min(pa[2] - ez, pb[2] - ez);
        this._max[0] = Math.max(pa[0] + ex, pb[0] + ex);
        this._max[1] = Math.max(pa[1] + ey, pb[1] + ey);
        this._max[2] = Math.max(pa[2] + ez, pb[2] + ez);
    }
}
