import { vec3 } from "gl-matrix";
import { ColorHelper } from "./color.js";
import { MathHelper } from "./math.js";
export class PaletteHelper {
    static resample(colorsIn, divisionsOut, reverse) {
        const divisionsIn = colorsIn.length / 3;
        const colorsOut = new Uint8Array(divisionsOut * 4);
        for (let i = 0; i < divisionsOut; i++) {
            const positionOut = (i + 0.5) / divisionsOut;
            const positionIn = positionOut * (divisionsIn - 1);
            const stepIn = Math.floor(positionIn);
            const fractIn = positionIn - stepIn;
            const j = reverse ? divisionsOut - i - 1 : i;
            colorsOut[j * 4] = MathHelper.lerp(colorsIn[stepIn * 3], colorsIn[(stepIn + 1) * 3], fractIn);
            colorsOut[j * 4 + 1] = MathHelper.lerp(colorsIn[stepIn * 3 + 1], colorsIn[(stepIn + 1) * 3 + 1], fractIn);
            colorsOut[j * 4 + 2] = MathHelper.lerp(colorsIn[stepIn * 3 + 2], colorsIn[(stepIn + 1) * 3 + 2], fractIn);
            colorsOut[j * 4 + 3] = 255;
        }
        return colorsOut;
    }
    static truncate(colorsIn, divisionsOut, reverse) {
        const divisionsIn = colorsIn.length / 3;
        const colorsOut = new Uint8Array(divisionsOut * 4);
        for (let i = 0; i < Math.min(divisionsIn, divisionsOut); i++) {
            const j = reverse ? divisionsOut - i - 1 : i;
            colorsOut[j * 4] = colorsIn[i * 3];
            colorsOut[j * 4 + 1] = colorsIn[i * 3 + 1];
            colorsOut[j * 4 + 2] = colorsIn[i * 3 + 2];
            colorsOut[j * 4 + 3] = 255;
        }
        return colorsOut;
    }
    static resampleStops(stops, divisions, reverse) {
        const colorsOut = new Uint8Array(divisions * 4);
        let from = 0;
        let to = 0;
        for (let i = 0; i < divisions; i++) {
            const positionOut = (i + 0.5) / divisions;
            while (stops[from].position < positionOut && from < stops.length - 1) {
                from++;
            }
            from = Math.max(from - 1, 0);
            to = Math.min(from + 1, stops.length - 1);
            const fromStop = stops[from];
            const toStop = stops[to];
            const fract = from == to ? 0 : (positionOut - fromStop.position) / (toStop.position - fromStop.position);
            const j = reverse ? divisions - i - 1 : i;
            colorsOut[j * 4] = MathHelper.lerp(fromStop.r, toStop.r, fract);
            colorsOut[j * 4 + 1] = MathHelper.lerp(fromStop.g, toStop.g, fract);
            colorsOut[j * 4 + 2] = MathHelper.lerp(fromStop.b, toStop.b, fract);
            colorsOut[j * 4 + 3] = 255;
        }
        return colorsOut;
    }
    static lerpRgb(from, to, divisions) {
        const colors = new Uint8Array(divisions * 4);
        for (let i = 0; i < divisions; i++) {
            const amount = i / (divisions - 1);
            colors[i * 4] = MathHelper.lerp(from[0], to[0], amount);
            colors[i * 4 + 1] = MathHelper.lerp(from[1], to[1], amount);
            colors[i * 4 + 2] = MathHelper.lerp(from[2], to[2], amount);
            colors[i * 4 + 3] = 0xff;
        }
        return colors;
    }
    static lerpHsv(from, to, divisions) {
        const colors = new Uint8Array(divisions * 4);
        for (let i = 0; i < divisions; i++) {
            const amount = i / (divisions - 1);
            const h = MathHelper.lerp(from[0], to[0], amount);
            const s = MathHelper.lerp(from[1], to[1], amount);
            const v = MathHelper.lerp(from[2], to[2], amount);
            ColorHelper.hsvToRgb(h, s, v, PaletteHelper._rgb);
            colors[i * 4] = PaletteHelper._rgb[0] * 0xff;
            colors[i * 4 + 1] = PaletteHelper._rgb[1] * 0xff;
            colors[i * 4 + 2] = PaletteHelper._rgb[2] * 0xff;
            colors[i * 4 + 3] = 0xff;
        }
        return colors;
    }
}
PaletteHelper._rgb = vec3.create();
