import { quat, vec3 } from "gl-matrix";
export const LightType = {
    distant: 0,
    sphere: 1,
    rect: 2,
    disc: 3,
    cylinder: 4,
    dome: 5,
};
export class LightBufferData extends Float32Array {
    constructor(count) {
        super(count * LightBufferData.SIZE);
        this.ROTATION_OFFSET = 0 / 4;
        this.CENTER_OFFSET = 16 / 4;
        this.TYPE_OFFSET = 28 / 4;
        this.SIZE_OFFSET = 32 / 4;
        this.COLOR_OFFSET = 48 / 4;
    }
    getType(index) {
        return this[LightBufferData.SIZE * index + this.TYPE_OFFSET];
    }
    setType(index, value) {
        this[LightBufferData.SIZE * index + this.TYPE_OFFSET] = value;
    }
    getCenter(index, value) {
        const offset = LightBufferData.SIZE * index + this.CENTER_OFFSET;
        vec3.set(value, this[offset], this[offset + 1], this[offset + 2]);
    }
    setCenter(index, value) {
        const offset = LightBufferData.SIZE * index + this.CENTER_OFFSET;
        this[offset] = value[0];
        this[offset + 1] = value[1];
        this[offset + 2] = value[2];
    }
    getSize(index, value) {
        const offset = LightBufferData.SIZE * index + this.SIZE_OFFSET;
        vec3.set(value, this[offset], this[offset + 1], this[offset + 2]);
    }
    setSize(index, value) {
        const offset = LightBufferData.SIZE * index + this.SIZE_OFFSET;
        this[offset] = value[0];
        this[offset + 1] = value[1];
        this[offset + 2] = value[2];
    }
    getColor(index, value) {
        const offset = LightBufferData.SIZE * index + this.COLOR_OFFSET;
        vec3.set(value, this[offset], this[offset + 1], this[offset + 2]);
    }
    setColor(index, value) {
        const offset = LightBufferData.SIZE * index + this.COLOR_OFFSET;
        this[offset] = value[0];
        this[offset + 1] = value[1];
        this[offset + 2] = value[2];
    }
    getRotation(index, value) {
        const offset = LightBufferData.SIZE * index + this.ROTATION_OFFSET;
        quat.set(value, this[offset], this[offset + 1], this[offset + 2], this[offset + 3]);
    }
    setRotation(index, value) {
        const offset = LightBufferData.SIZE * index + this.ROTATION_OFFSET;
        this[offset] = value[0];
        this[offset + 1] = value[1];
        this[offset + 2] = value[2];
        this[offset + 3] = value[3];
    }
}
LightBufferData.SIZE = 64 / 4;
export class Light {
    constructor(options) {
        this.color = options.color;
        this.center = options.center;
    }
    toBuffer(buffer, index) {
        buffer.setCenter(index, this.center);
        buffer.setColor(index, this.color);
    }
}
export class SphereLight extends Light {
    constructor(options) {
        super(options);
        this.radius = options.radius / 2;
    }
    toBuffer(buffer, index) {
        super.toBuffer(buffer, index);
        buffer.setType(index, LightType.sphere);
        buffer.setSize(index, vec3.fromValues(this.radius, this.radius, this.radius));
    }
}
export class RectLight extends Light {
    constructor(options) {
        super(options);
        this._thickness = 0.00001;
        this.size = options.size;
        this.rotation = options.rotation;
    }
    toBuffer(buffer, index) {
        super.toBuffer(buffer, index);
        buffer.setType(index, LightType.rect);
        buffer.setSize(index, vec3.fromValues(this.size[0], this.size[1], this._thickness));
        buffer.setRotation(index, this.rotation);
    }
}
