export class SetHelper {
    static new(a, b) {
        a.clear();
        for (let item of b) {
            a.add(item);
        }
    }
    static union(a, b) {
        for (let item of b) {
            a.add(item);
        }
    }
    static intersection(a, b) {
        const c = new Set(b);
        for (let item of a) {
            if (!c.has(item)) {
                a.delete(item);
            }
        }
        for (let item of b) {
            if (!a.has(item)) {
                a.delete(item);
            }
        }
    }
    static symmetricDifference(a, b) {
        for (let item of b) {
            if (a.has(item)) {
                a.delete(item);
            }
            else {
                a.add(item);
            }
        }
    }
    static difference(a, b) {
        for (let item of b) {
            a.delete(item);
        }
    }
}
