import { vec3 } from "gl-matrix";
export class ColorHelper {
    static luminance(rgb) {
        return rgb[0] * ColorHelper.LUMINANCE[0] + rgb[1] * ColorHelper.LUMINANCE[1] + rgb[2] * ColorHelper.LUMINANCE[2];
    }
    static rgbToHex(r, g, b) {
        const r2 = `0${Math.round(r * 255).toString(16)}`;
        const g2 = `0${Math.round(g * 255).toString(16)}`;
        const b2 = `0${Math.round(b * 255).toString(16)}`;
        return `#${r2.substr(r2.length - 2, 2)}${g2.substr(g2.length - 2, 2)}${b2.substr(b2.length - 2, 2)}`;
    }
    static rgbToHsv(r, g, b, hsv) {
        let h, s, v, delta;
        const min = Math.min(Math.min(r, g), b);
        const max = Math.max(Math.max(r, g), b);
        delta = max - min;
        v = max;
        if (delta == 0) {
            h = -1;
            if (max == 0) {
                s = -1;
            }
            else {
                s = 0;
            }
            hsv[0] = h;
            hsv[1] = s;
            hsv[2] = v;
        }
        s = delta / max;
        if (r == max) {
            h = (g - b) / delta;
        }
        else if (g == max) {
            h = 2 + (b - r) / delta;
        }
        else {
            h = 4 + (r - g) / delta;
        }
        h *= 60;
        if (h < 0) {
            h += 360;
        }
        hsv[0] = h;
        hsv[1] = s;
        hsv[2] = v;
    }
    static hsvToRgb(h, s, v, rgb) {
        let sextant, r, g, b;
        if (s == 0) {
            r = g = b = v;
            rgb[0] = r;
            rgb[1] = g;
            rgb[2] = b;
        }
        let frac, p, q, t;
        h %= 360;
        h /= 60;
        sextant = Math.floor(h);
        frac = h - sextant;
        p = v * (1 - s);
        q = v * (1 - s * frac);
        t = v * (1 - s * (1 - frac));
        switch (sextant) {
            case 0:
                r = v;
                g = t;
                b = p;
                break;
            case 1:
                r = q;
                g = v;
                b = p;
                break;
            case 2:
                r = p;
                g = v;
                b = t;
                break;
            case 3:
                r = p;
                g = q;
                b = v;
                break;
            case 4:
                r = t;
                g = p;
                b = v;
                break;
            default:
                r = v;
                g = p;
                b = q;
                break;
        }
        rgb[0] = r;
        rgb[1] = g;
        rgb[2] = b;
    }
}
ColorHelper.LUMINANCE = vec3.fromValues(0.2126, 0.7152, 0.0722);
