import { SandDance } from '@msrvida/sanddance-react';
function comparableGroup(group) {
    return Object.assign(Object.assign({}, group), { clause: null });
}
function compareGroup(a, b) {
    return SandDance.searchExpression.compareGroup(comparableGroup(a), comparableGroup(b));
}
export function compareGroups(haystack, needle) {
    const groups = [];
    let found = false;
    //look for item in all
    haystack.forEach(group => {
        if (compareGroup(group, needle)) {
            //if it exists, don't add it
            found = true;
        }
        else {
            groups.push(group);
        }
    });
    return { groups, found };
}
export function createInputSearch(search) {
    const groups = SandDance.searchExpression.ensureSearchExpressionGroupArray(search);
    const dialogSearch = groups.map((group, groupIndex) => {
        return Object.assign(Object.assign({ key: groupIndex }, group), { expressions: group.expressions.map((ex, i) => {
                const ex2 = Object.assign({ key: i }, ex);
                return ex2;
            }) });
    });
    return dialogSearch;
}
