export function notNice(niceValue) {
    //convert "nice" numbers to numeric value
    return (niceValue + '').replace(/[\s,]/g, '');
}
function tickValue(axis, i) {
    const tick = axis.tickText[i];
    let value;
    if (tick) {
        value = axis.tickText[i].value;
    }
    return { tick, value };
}
export function selectNullOrEmpty(column) {
    const searchExpression = {
        name: column.name,
        operator: 'isnullorEmpty',
    };
    return searchExpression;
}
export function selectExact(column, value) {
    if (value == null) {
        return selectNullOrEmpty(column);
    }
    const searchExpression = {
        name: column.name,
        operator: '==',
        value,
    };
    return searchExpression;
}
export function selectNone(column, values) {
    const expressions = values.map((value, i) => {
        const searchExpression = {
            name: column.name,
            operator: '!=',
            value,
        };
        if (i) {
            searchExpression.clause = '&&';
        }
        return searchExpression;
    });
    const searchExpressionGroup = {
        expressions,
    };
    return searchExpressionGroup;
}
export function selectExactAxis(axis, column, i) {
    const result = tickValue(axis, i);
    if (result.tick) {
        return selectExact(column, result.value);
    }
}
export function selectBetween(column, lowValue, highValue, lowOperator = '>=', highOperator = '<') {
    const expressions = [];
    if (lowValue !== undefined) {
        expressions.push({
            name: column.name,
            operator: lowOperator,
            value: lowValue,
        });
    }
    if (highValue !== undefined) {
        expressions.push({
            name: column.name,
            operator: highOperator,
            value: highValue,
        });
    }
    if (expressions.length > 1) {
        expressions[1].clause = '&&';
    }
    const searchExpressionGroup = {
        expressions,
    };
    return searchExpressionGroup;
}
export function selectBetweenAxis(axis, column, i) {
    const low = tickValue(axis, i);
    const high = tickValue(axis, i + 1);
    return selectBetween(column, low.value, high.value);
}
