import { Filter } from "./filter.js";
export class Table {
    get data() { return this._data; }
    get headings() { return this._headings; }
    get all() { return this._all; }
    get isInitialized() { return this._isInitialized; }
    get filter() { return this._filter; }
    set filter(value) {
        if (this._filter !== value) {
            this._filter = value;
            if (this.filterChangedCallback) {
                this.filterChangedCallback();
            }
        }
    }
    getColumnType(column) {
        return this._columnTypes[column];
    }
    isColumnDiscrete(column) {
        return (this._columnTypes[column] & ColumnType.discrete) > 0;
    }
    isColumnNumeric(column) {
        return (this._columnTypes[column] & ColumnType.numeric) > 0;
    }
    isColumnContinuous(column) {
        return (this._columnTypes[column] & ColumnType.continuous) > 0;
    }
    constructor(core, headings, data, columnTypes) {
        this._core = core;
        this._headings = headings;
        this._data = data;
        this._columnTypes = columnTypes;
        this._numericValues = Array(columnTypes.length).fill(null);
        const indices = new Uint32Array(data.length);
        for (let i = 0; i < indices.length; i++) {
            indices[i] = i;
        }
        this._all = new Filter(core, indices, data, headings, columnTypes, this._numericValues);
        this._isInitialized = true;
    }
    createFilter(ids) {
        return new Filter(this._core, ids, this._data, this._headings, this._columnTypes, this._numericValues);
    }
}
export const ColumnType = {
    none: 0,
    float: 1,
    integer: 2,
    string: 4,
    date: 8,
    continuous: 9,
    discrete: 6,
    numeric: 11
};
