export function allowNoneForSize(specContext) {
    switch (specContext.insight.totalStyle) {
        case 'sum-strip':
        case 'sum-strip-percent':
        case 'sum-treemap':
            return false;
        default:
            //if totalStyle is blank, count is assumed
            return true;
    }
}
