import { FieldNames } from './constants';
import { safeFieldName } from './expr';
export function createOrdinals(source, prefix, binFields, sortOrder) {
    const _binFields = binFields.map(safeFieldName);
    const dataName = `${prefix}_bin_order`;
    const data = {
        name: dataName,
        source,
        transform: [
            {
                type: 'aggregate',
                groupby: _binFields,
            },
            {
                type: 'collect',
                sort: {
                    field: _binFields,
                    order: _binFields.map(f => sortOrder),
                },
            },
            {
                type: 'window',
                ops: ['row_number'],
                as: [FieldNames.Ordinal],
            },
        ],
    };
    return {
        data,
        scale: ordinalScale(dataName, `scale_${prefix}_order`, binFields),
    };
}
export function ordinalScale(dataName, scaleName, binFields) {
    return {
        type: 'ordinal',
        name: scaleName,
        domain: {
            data: dataName,
            field: safeFieldName(binFields[0]),
        },
        range: {
            data: dataName,
            field: FieldNames.Ordinal,
        },
    };
}
