import { MathHelper } from "./math.js";
import { AngleHelper } from "./angle.js";
import { Constants } from "../constants.js";
export class MercatorHelper {
    constructor() {
        this.minLatitude = -85.05112878;
        this.maxLatitude = 85.05112878;
        this.minLongitude = -180;
        this.maxLongitude = 180;
        this.minX = -1;
        this.minY = -1;
        this.maxX = 1;
        this.maxY = 1;
    }
    project(longitude, latitude, xy) {
        const x = longitude / 180;
        latitude = MathHelper.clamp(latitude, this.minLatitude, this.maxLatitude);
        latitude = AngleHelper.degreesToRadians(latitude);
        const sinLatitude = Math.sin(latitude);
        let y = Math.log((1 + sinLatitude) / (1 - sinLatitude)) / 2;
        y = MathHelper.clamp(y / Math.PI, this.minY, this.maxY);
        xy[0] = x;
        xy[1] = y;
    }
    unproject(x, y, lonLat) {
        const longitude = x * 180;
        y *= Math.PI;
        let latitude = Constants.PI_OVER_TWO - 2 * Math.atan(Math.exp(-y));
        latitude = AngleHelper.radiansToDegrees(latitude);
        lonLat[0] = longitude;
        lonLat[1] = latitude;
    }
}
export class AlbersHelper {
    constructor() {
        this._phi1 = 29.5;
        this._phi2 = 45.5;
        this._lat0 = 37.5;
        this._lon0 = -96;
    }
    get standardParallel1() { return this._phi1; }
    set standardParallel1(value) { this._phi1 = value; }
    get standardParallel2() { return this._phi2; }
    set standardParallel2(value) { this._phi2 = value; }
    get latitudeOfOrigin() { return this._lat0; }
    set latitudeOfOrigin(value) { this._lat0 = value; }
    get centralMeridian() { return this._lon0; }
    set centralMeridian(value) { this._lon0 = value; }
    project(lon, lat, xy) {
        const phi1 = AngleHelper.degreesToRadians(this._phi1);
        const phi2 = AngleHelper.degreesToRadians(this._phi2);
        const lat0 = AngleHelper.degreesToRadians(this._lat0);
        const lon0 = AngleHelper.degreesToRadians(this._lon0);
        lat = AngleHelper.degreesToRadians(lat);
        lon = AngleHelper.degreesToRadians(lon);
        const n = 0.5 * (Math.sin(phi1) + Math.sin(phi2));
        const c = Math.cos(phi1);
        const C = c * c + 2 * n * Math.sin(phi1);
        const p0 = Math.sqrt(C - 2 * n * Math.sin(lat0)) / n;
        const theta = n * (lon - lon0);
        const p = Math.sqrt(C - 2 * n * Math.sin(lat)) / n;
        const x = p * Math.sin(theta);
        const y = p0 - p * Math.cos(theta);
        xy[0] = x;
        xy[1] = y;
    }
    unproject(x, y, lonLat) {
        const phi1 = AngleHelper.degreesToRadians(this._phi1);
        const phi2 = AngleHelper.degreesToRadians(this._phi2);
        const lat0 = AngleHelper.degreesToRadians(this._lat0);
        const lon0 = AngleHelper.degreesToRadians(this._lon0);
        const n = 0.5 * (Math.sin(phi1) + Math.sin(phi2));
        const c = Math.cos(phi1);
        const C = c * c + 2 * n * Math.sin(phi1);
        const p0 = Math.sqrt(C - 2 * n * Math.sin(lat0)) / n;
        let theta = Math.atan(x / Math.abs((p0 - y)) * Math.sign(p0 - y));
        if ((p0 - y) * n < 0) {
            theta -= Math.PI * Math.sign(x) * Math.sign(p0 - y);
        }
        const p = Math.sqrt(x * x + Math.pow(p0 - y, 2));
        const lon = lon0 + theta / n;
        const lat = Math.asin((C - p * p * n * n) / (2 * n));
        lonLat[0] = AngleHelper.radiansToDegrees(lon);
        lonLat[1] = AngleHelper.radiansToDegrees(lat);
    }
}
export class GeoJSONHelper {
    constructor() {
        this._lonLat = [0, 0];
    }
    feature(geoJSON, property, key) {
        for (let i = 0; i < geoJSON.features.length; i++) {
            let feature = geoJSON.features[i];
            if (feature.properties[property] == key) {
                return feature;
            }
        }
        return null;
    }
    bounds(geometry, clip, projection) {
        let minX = Number.MAX_VALUE;
        let maxX = -Number.MAX_VALUE;
        let minY = Number.MAX_VALUE;
        let maxY = -Number.MAX_VALUE;
        switch (geometry.type) {
            case "Polygon":
                const polygon = geometry;
                const outer = polygon.coordinates[0];
                for (let k = 0; k < outer.length; k++) {
                    this._lonLat[0] = outer[k][0];
                    this._lonLat[1] = outer[k][1];
                    if (this._lonLat[0] < clip.minLon || this._lonLat[0] > clip.maxLon || this._lonLat[1] < clip.minLat || this._lonLat[1] > clip.maxLat) {
                        break;
                    }
                    if (this._lonLat[0] > 0) {
                        this._lonLat[0] -= 360;
                    }
                    if (projection) {
                        projection.project(this._lonLat[0], this._lonLat[1], this._lonLat);
                    }
                    minX = Math.min(minX, this._lonLat[0]);
                    maxX = Math.max(maxX, this._lonLat[0]);
                    minY = Math.min(minY, this._lonLat[1]);
                    maxY = Math.max(maxY, this._lonLat[1]);
                }
                break;
            case "MultiPolygon":
                const multiPolygon = geometry;
                for (let j = 0; j < multiPolygon.coordinates.length; j++) {
                    const polygon = multiPolygon.coordinates[j];
                    const outer = polygon[0];
                    for (let k = 0; k < outer.length; k++) {
                        this._lonLat[0] = outer[k][0];
                        this._lonLat[1] = outer[k][1];
                        if (this._lonLat[0] < clip.minLon || this._lonLat[0] > clip.maxLon || this._lonLat[1] < clip.minLat || this._lonLat[1] > clip.maxLat) {
                            continue;
                        }
                        if (this._lonLat[0] > 0) {
                            this._lonLat[0] -= 360;
                        }
                        if (projection) {
                            projection.project(this._lonLat[0], this._lonLat[1], this._lonLat);
                        }
                        minX = Math.min(minX, this._lonLat[0]);
                        maxX = Math.max(maxX, this._lonLat[0]);
                        minY = Math.min(minY, this._lonLat[1]);
                        maxY = Math.max(maxY, this._lonLat[1]);
                    }
                }
                break;
        }
        if (minX == Number.MAX_VALUE) {
            minX = 0;
            maxX = 0;
            minY = 0;
            maxY = 0;
        }
        return { minX: minX, maxX: maxX, minY: minY, maxY: maxY };
    }
}
