import { mat4, vec3 } from "gl-matrix";
import { Quad as QuadMesh } from "../../../meshes/quad.js";
export class Quad {
    get isInitialized() { return this._isInitialized; }
    get vertexBuffer() { return this._vertexBuffer; }
    get indexBuffer() { return this._indexBuffer; }
    get indexCount() { return this._indexCount; }
    initializeContext(gl) {
        const _vec3 = vec3.fromValues(2, 2, 2);
        const _mat4 = mat4.create();
        mat4.fromScaling(_mat4, _vec3);
        const vertices = QuadMesh.positions(_mat4);
        this._vertexBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, this._vertexBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.STATIC_DRAW);
        const indices = QuadMesh.INDICES;
        this._indexBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this._indexBuffer);
        gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indices, gl.STATIC_DRAW);
        this._indexCount = indices.length;
        this._isInitialized = true;
    }
}
