import { quat, vec2, vec3 } from "gl-matrix";
import { ImageQuad, ImageSphere } from "../../components/image.js";
import { HittableRotatedXyRect, HittableSphere } from "./hittable.js";
export class ImageVisual {
    get isInitialized() { return this._isInitialized; }
    get image() { return this._image; }
    render(elapsedTime) { }
    constructor(core, main, image) {
        this._core = core;
        this._main = main;
        this._image = image;
        this.isVisible = true;
        image.hasChangedCallback = () => { this._hasChanged = true; };
    }
    initializeContext(device) {
        if (!this._image.isInitialized) {
            this._image.initialize();
        }
        this._hasChanged = true;
        this._isInitialized = true;
    }
    update() {
        if (this._hasChanged && this._isInitialized) {
            this._hasChanged = false;
            const material = this._image.material == -1 ? this._main.config.defaultMaterial : this._main.materials[this._image.material];
            const modelPosition = vec3.create();
            const modelScale = this._core.getModelScale();
            const modelRotation = quat.create();
            this._core.getModelRotation(modelRotation);
            const modelSizeX = this._image.maxBoundsX - this._image.minBoundsX;
            const modelSizeY = this._image.maxBoundsY - this._image.minBoundsY;
            const modelSizeZ = this._image.maxBoundsZ - this._image.minBoundsZ;
            const maxBounds = Math.max(modelSizeX, Math.max(modelSizeY, modelSizeZ));
            const boundsScaling = maxBounds == 0 ? 1 : 1 / maxBounds;
            vec3.set(modelPosition, this._main.mMatrix[12], this._main.mMatrix[13], this._main.mMatrix[14]);
            if (this._image instanceof ImageQuad) {
                const imageQuad = this._image;
                const position = vec3.fromValues((imageQuad.minBoundsX + imageQuad.maxBoundsX) / 2, (imageQuad.minBoundsY + imageQuad.maxBoundsY) / 2, (imageQuad.minBoundsZ + imageQuad.maxBoundsZ) / 2);
                vec3.subtract(position, imageQuad.position, position);
                vec3.scale(position, position, boundsScaling);
                vec3.scale(position, position, modelScale);
                vec3.transformQuat(position, position, modelRotation);
                vec3.add(position, position, modelPosition);
                const hittableRotatedXyRectOptions = {
                    center0: position,
                    center1: position,
                    time0: 1,
                    time1: 1,
                    size0: vec2.fromValues(imageQuad.width * boundsScaling * modelScale / 2, imageQuad.height * boundsScaling * modelScale / 2),
                    size1: vec2.fromValues(imageQuad.width * boundsScaling * modelScale / 2, imageQuad.height * boundsScaling * modelScale / 2),
                    material: material,
                    texCoord0: imageQuad.texCoord0,
                    texCoord1: imageQuad.texCoord1,
                    rotation0: imageQuad.rotation,
                    rotation1: imageQuad.rotation,
                };
                this.hittable = new HittableRotatedXyRect(hittableRotatedXyRectOptions);
            }
            else if (this._image instanceof ImageSphere) {
                const imageSphere = this._image;
                const position = imageSphere.position;
                vec3.subtract(position, imageSphere.position, position);
                vec3.scale(position, position, boundsScaling);
                vec3.scale(position, position, modelScale);
                vec3.transformQuat(position, position, modelRotation);
                vec3.add(position, position, modelPosition);
                const hittableSphereOptions = {
                    center0: position,
                    center1: position,
                    time0: 1,
                    time1: 1,
                    radius: imageSphere.radius * boundsScaling,
                    material: material,
                };
                this.hittable = new HittableSphere(hittableSphereOptions);
            }
            if (this.hasChangedCallback) {
                this.hasChangedCallback();
            }
        }
    }
}
