import { quat, vec3 } from "gl-matrix";
import { Constants } from "../constants.js";
import { CameraBase } from "./camera.js";
export class OrbitCamera extends CameraBase {
    getTwist(value) { quat.copy(value, this._cameraRotation); }
    setTwist(value, isSmooth) {
        quat.copy(this._cameraRotation, value);
        if (!isSmooth) {
            quat.copy(this._smoothedCameraRotation, value);
        }
    }
    ;
    twist(angle, x, y) {
        this.unproject(this._vec3, x, y, 1);
        vec3.normalize(this._vec3, this._vec3);
        vec3.transformQuat(this._vec3, this._vec3, this._orbitRotation);
        this._twist(this._vec3, angle);
    }
    _twist(axis, angle) {
        quat.setAxisAngle(this._quat, axis, angle);
        quat.multiply(this._cameraRotation, this._quat, this._cameraRotation);
    }
    rotate(translationDelta) {
        vec3.set(this._vec3, translationDelta[1], translationDelta[0], 0);
        const length = vec3.length(this._vec3);
        const angle = length * Constants.PI / Math.min(this.width, this.height);
        vec3.scale(this._vec3, this._vec3, 1 / length);
        quat.setAxisAngle(this._quat, this._vec3, angle);
        quat.multiply(this._orbitRotation, this._quat, this._orbitRotation);
    }
}
