import { LogLevel } from "../../main.js";
export class FontVisual {
    get isInitialized() { return this._isInitialized; }
    get font() { return this._font; }
    constructor(core, font) {
        this._core = core;
        this._font = font;
        font.hasChangedCallback = () => { this._hasChanged = true; };
    }
    initializeContext(device) {
        this._device = device;
        this._hasChanged = true;
        this._isInitialized = true;
    }
    update() {
        if (this._hasChanged && this._isInitialized) {
            this._hasChanged = false;
            const start = window.performance.now();
            const imageData = this._font.atlas.imageData;
            const textureSize = {
                width: imageData.width,
                height: imageData.height,
            };
            createImageBitmap(imageData).then((imageBitmap) => {
                const textureDescriptor = {
                    size: textureSize,
                    format: 'rgba8unorm',
                    usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST | GPUTextureUsage.RENDER_ATTACHMENT,
                };
                this.texture = this._device.createTexture(textureDescriptor);
                const imageCopyExternalImage = {
                    source: imageBitmap,
                };
                const imageCopyTextureTagged = {
                    texture: this.texture,
                };
                const copySize = {
                    width: imageData.width,
                    height: imageData.height,
                };
                this._device.queue.copyExternalImageToTexture(imageCopyExternalImage, imageCopyTextureTagged, copySize);
                if (this.hasChangedCallback) {
                    this.hasChangedCallback();
                }
                this._core.log.write(LogLevel.info, `${this._font.name} texture updated ${Math.round(window.performance.now() - start)}ms`);
            });
        }
    }
}
