import { LogLevel } from "./main.js";
export class Log {
    constructor(core) {
        this._core = core;
    }
    write(level, value) {
        if (level >= this._core.config.logLevel) {
            switch (level) {
                case LogLevel.trace:
                    console.trace(value);
                    break;
                case LogLevel.debug:
                    console.debug(value);
                    break;
                case LogLevel.info:
                    console.info(value);
                    break;
                case LogLevel.warn:
                    console.warn(value);
                    break;
                case LogLevel.error:
                    console.error(value);
                    break;
            }
        }
    }
}
