import { vec3 } from "gl-matrix";
import { MathHelper } from "../helpers/math.js";
import { AngleHelper } from "../helpers/angle.js";
export class ManipulationProcessor {
    get manipulators() { return this._manipulators; }
    get count() { return this._count; }
    get isDragging() { return this._isDragging; }
    constructor(core) {
        this._core = core;
        this._count = 0;
        this._centroid = vec3.create();
        this._previousCentroid = vec3.create();
        this._relativePositionToCentroid = vec3.create();
        this._directionToCentroid = vec3.create();
        this._previousDirectionToCentroid = vec3.create();
        this._manipulators = {};
        this._removedManipulators = [];
        this.cumulativeTranslation = vec3.create();
        this.translationDelta = vec3.create();
        this.centroid = vec3.create();
        this.maxScale = Number.MAX_VALUE;
        this.twistAxis = vec3.fromValues(0, 0, 1);
        this.initialize();
    }
    update(elapsedTime, manipulators) {
        for (const key in this._manipulators) {
            const manipulator = this._manipulators[key];
            if (!manipulators[manipulator.id]) {
                if (this.removeManipulator) {
                    this.removeManipulator(manipulator);
                }
                this._removedManipulators.push(manipulator.id);
            }
        }
        if (this._removedManipulators.length > 0) {
            for (let i = 0; i < this._removedManipulators.length; i++) {
                delete this._manipulators[this._removedManipulators[i]];
                this._count--;
            }
            this._removedManipulators = [];
        }
        for (const key in manipulators) {
            const manipulator = manipulators[key];
            if (!this._manipulators[manipulator.id]) {
                if (!this.addManipulator || this.addManipulator(manipulator)) {
                    vec3.copy(manipulator.initialPosition, manipulator.position);
                    this._manipulators[manipulator.id] = manipulator;
                    this._count++;
                }
            }
        }
        vec3.set(this.translationDelta, 0, 0, 0);
        this.scaleDelta = 0;
        this.twistDelta = 0;
        if (this._count > 0) {
            if (this._previousCount > 0) {
                if (this.prepareManipulation) {
                    this.prepareManipulation();
                }
                this._process();
                if (this.processManipulation) {
                    this.processManipulation(elapsedTime);
                }
            }
            else {
                this.initialize();
                if (this.beginManipulation) {
                    this.beginManipulation();
                }
            }
        }
        else {
            if (this._previousCount > 0) {
                if (this.endManipulation) {
                    this.endManipulation();
                }
            }
        }
        this._isDragging = (this._count == 1 && vec3.squaredLength(this.cumulativeTranslation) > this._core.config.dragToleranceSquared) || this._count > 1;
        this._previousCount = this._count;
    }
    initialize() {
        vec3.set(this.centroid, 0, 0, 0);
        vec3.set(this.cumulativeTranslation, 0, 0, 0);
        this.cumulativeScale = 1;
        this.cumulativeTwist = 0;
    }
    _process() {
        if (this._previousCount > 0) {
            let persisted = 0;
            for (const key in this._manipulators) {
                const manipulator = this._manipulators[key];
                if (manipulator.isPersisted) {
                    persisted++;
                }
            }
            const removed = this._previousCount - persisted;
            if (persisted > 0) {
                if (removed > 0) {
                    vec3.copy(this._centroid, this._previousCentroid);
                }
                else {
                    vec3.set(this._centroid, 0, 0, 0);
                    for (const key in this._manipulators) {
                        const manipulator = this._manipulators[key];
                        if (manipulator.isPersisted) {
                            vec3.add(this._centroid, this._centroid, manipulator.position);
                        }
                    }
                    vec3.scale(this._centroid, this._centroid, 1 / persisted);
                }
                for (const key in this._manipulators) {
                    const manipulator = this._manipulators[key];
                    if (manipulator.isPersisted) {
                        manipulator.maxTranslationSquared = Math.max(manipulator.maxTranslationSquared, vec3.squaredDistance(manipulator.position, manipulator.initialPosition));
                        vec3.add(this.translationDelta, this.translationDelta, manipulator.position);
                        vec3.subtract(this.translationDelta, this.translationDelta, manipulator.previousPosition);
                        vec3.subtract(this._relativePositionToCentroid, manipulator.position, this._centroid);
                        const distanceToCentroidSquared = vec3.squaredLength(this._relativePositionToCentroid);
                        if (distanceToCentroidSquared < this._core.config.manipulatorMinRelativeDistanceSquared) {
                            this.scaleDelta += 1;
                        }
                        else {
                            const distanceToCentroid = Math.sqrt(distanceToCentroidSquared);
                            const previousDistanceToCentroidSquared = vec3.squaredLength(manipulator.previousPositionRelativeToCentroid);
                            const previousDistanceToCentroid = Math.sqrt(previousDistanceToCentroidSquared);
                            this.scaleDelta += distanceToCentroid / previousDistanceToCentroid;
                            vec3.scale(this._directionToCentroid, this._relativePositionToCentroid, 1 / distanceToCentroid);
                            vec3.scale(this._previousDirectionToCentroid, manipulator.previousPositionRelativeToCentroid, 1 / previousDistanceToCentroid);
                            this.twistDelta += AngleHelper.signedAngleBetweenVectors(this._previousDirectionToCentroid, this._directionToCentroid, this.twistAxis);
                        }
                    }
                }
                vec3.scale(this.translationDelta, this.translationDelta, 1 / persisted);
                vec3.add(this.cumulativeTranslation, this.cumulativeTranslation, this.translationDelta);
                this.scaleDelta /= persisted;
                this.cumulativeScale = MathHelper.clamp(this.cumulativeScale * this.scaleDelta, this.minScale, this.maxScale);
                this.scaleDelta -= 1;
                this.twistDelta /= persisted;
                this.cumulativeTwist += this.twistDelta;
            }
        }
        vec3.set(this.centroid, 0, 0, 0);
        for (const key in this._manipulators) {
            const manipulator = this._manipulators[key];
            vec3.add(this.centroid, this.centroid, manipulator.position);
        }
        vec3.scale(this.centroid, this.centroid, 1 / this._count);
        for (const key in this._manipulators) {
            const manipulator = this._manipulators[key];
            vec3.subtract(manipulator.positionRelativeToCentroid, manipulator.position, this.centroid);
        }
        vec3.copy(this._previousCentroid, this.centroid);
        for (const key in this._manipulators) {
            const manipulator = this._manipulators[key];
            manipulator.isPersisted = true;
            vec3.copy(manipulator.previousPosition, manipulator.position);
            vec3.copy(manipulator.previousRotationAxis, manipulator.rotationAxis);
            vec3.copy(manipulator.previousPositionRelativeToCentroid, manipulator.positionRelativeToCentroid);
        }
    }
}
