import { quat, vec2, vec3 } from "gl-matrix";
import { PositionTexturePickVertex } from "../../vertex.js";
import { HittableRotatedFontXyRect } from "./hittable.js";
export class LabelSetVisual {
    get isInitialized() { return this._isInitialized; }
    get label() { return this._labelSet; }
    render(elapsedTime) { }
    constructor(core, main, labelSet) {
        this._core = core;
        this._main = main;
        this._labelSet = labelSet;
        this.isVisible = true;
        labelSet.hasChangedCallback = () => { this._hasChanged = true; };
        if (!this._labelSet.isInitialized) {
            this._labelSet.initialize();
        }
        if (this._labelSet.text && this._labelSet.text.length > 0) {
            this._hasChanged = true;
        }
        this._isInitialized = true;
    }
    update() {
        if (this._hasChanged && this._isInitialized) {
            this._hasChanged = false;
            this.hittables = [];
            const modelPosition = vec3.create();
            const modelScale = this._core.getModelScale();
            const modelRotation = quat.create();
            this._core.getModelRotation(modelRotation);
            vec3.set(modelPosition, this._main.mMatrix[12], this._main.mMatrix[13], this._main.mMatrix[14]);
            const glpyhRotation = quat.create();
            const glyphInvRotation = quat.create();
            const position0 = vec3.create();
            const position1 = vec3.create();
            const dataView = this._labelSet.verticesView;
            const labelCount = this._labelSet.text.length;
            let glyphIndex = 0;
            for (let i = 0; i < labelCount; i++) {
                const material = this._labelSet.material !== undefined ? this._main.materials[this._labelSet.material] : this._labelSet.materials ? this._main.materials[this._labelSet.materials[i]] : this._main.config.defaultTextMaterial;
                const glyphCount = this._labelSet.text[i].length;
                for (let j = 0; j < glyphCount; j++) {
                    PositionTexturePickVertex.getPosition(dataView, glyphIndex * 4 + 2, position0);
                    PositionTexturePickVertex.getPosition(dataView, glyphIndex * 4 + 1, position1);
                    vec3.scale(position0, position0, modelScale);
                    vec3.scale(position1, position1, modelScale);
                    vec3.transformQuat(position0, position0, modelRotation);
                    vec3.transformQuat(position1, position1, modelRotation);
                    vec3.add(position0, position0, modelPosition);
                    vec3.add(position1, position1, modelPosition);
                    const centroid = vec3.create();
                    vec3.add(centroid, position0, position1);
                    vec3.scale(centroid, centroid, 0.5);
                    if (this._labelSet.rotation) {
                        quat.set(glpyhRotation, this._labelSet.rotation[0], this._labelSet.rotation[1], this._labelSet.rotation[2], this._labelSet.rotation[3]);
                    }
                    else if (this._labelSet.rotations) {
                        quat.set(glpyhRotation, this._labelSet.rotations[i * 4], this._labelSet.rotations[i * 4 + 1], this._labelSet.rotations[i * 4 + 2], this._labelSet.rotations[i * 4 + 3]);
                    }
                    else {
                        quat.identity(glpyhRotation);
                    }
                    const rotation = quat.clone(glpyhRotation);
                    quat.multiply(rotation, modelRotation, rotation);
                    quat.conjugate(glyphInvRotation, rotation);
                    vec3.subtract(position0, position0, centroid);
                    vec3.subtract(position1, position1, centroid);
                    vec3.transformQuat(position0, position0, glyphInvRotation);
                    vec3.transformQuat(position1, position1, glyphInvRotation);
                    vec3.add(position0, position0, centroid);
                    vec3.add(position1, position1, centroid);
                    const texCoord0 = vec2.create();
                    const texCoord1 = vec2.create();
                    PositionTexturePickVertex.getTexCoord(dataView, glyphIndex * 4 + 2, texCoord0);
                    PositionTexturePickVertex.getTexCoord(dataView, glyphIndex * 4 + 1, texCoord1);
                    const hittableFontOptions = {
                        center0: centroid,
                        center1: centroid,
                        time0: 1,
                        time1: 1,
                        size0: vec2.fromValues((position1[0] - position0[0]) / 2, (position1[1] - position0[1]) / 2),
                        size1: vec2.fromValues((position1[0] - position0[0]) / 2, (position1[1] - position0[1]) / 2),
                        material: material,
                        texCoord0: texCoord0,
                        texCoord1: texCoord1,
                        rotation0: rotation,
                        rotation1: rotation,
                        sdfBuffer: this._core.config.sdfBuffer,
                    };
                    const hittable = new HittableRotatedFontXyRect(hittableFontOptions);
                    this.hittables.push(hittable);
                    glyphIndex++;
                }
            }
            if (this.hasChangedCallback) {
                this.hasChangedCallback();
            }
        }
    }
}
